UPDATE refund_record
SET refund_status='REFUND_SUCCESS',refund_time=#{refundTime},fail_reason=NULL,update_time=#{refundTime}
WHERE refund_id=#{refundId} AND refund_status='REFUNDING'

UPDATE ticket_order
SET order_status='REFUND_SUCCESS',payment_status='REFUNDED',update_time=#{refundTime}
WHERE order_id=#{orderId} AND order_status='REFUNDING' AND fulfillment_mode='TICKET_SOURCE'
